    'welcome.title': "Bienvenue sur AnonChat",
    'welcome.intro1': "Vous allez utiliser une messagerie privée et pair-à-pair. AnonChat utilise les services cachés du protocole Anyone pour connecter les utilisateurs.",
    'welcome.intro2': "Vos messages sont conçus pour rester entre vous et les personnes avec qui vous choisissez de parler. Votre adresse « *.anyone » est votre identité dans l’application.",
    'welcome.rememberTitle': "Rappel :",
    'welcome.r1': "Ne partagez jamais d’informations personnelles avec des personnes en qui vous n’avez pas confiance.",
    'welcome.r2': "Tout ce que vous envoyez peut être copié, enregistré ou partagé par le destinataire.",
    'welcome.r3': "Aucune technologie ne peut garantir un anonymat parfait.",
    'welcome.r4': "Le routage par services cachés offre généralement plus de confidentialité, mais des délais occasionnels de livraison et de connexion sont normaux.",
