    'settings.about': "Über",
    'about.title': "Über AnonChat",
    'about.version': "Version {v}",
    'about.intro': "AnonChat ist ein datenschutzorientierter Desktop-Messenger mit Ende-zu-Ende-Verschlüsselung, der als Hidden Service im Anyone-Netzwerk läuft. Es gibt keine Konten, keine Telefonnummern und keine zentralen Server.",
    'about.communityTitle': "Unabhängiges Community-Projekt",
    'about.community': "AnonChat ist keine offizielle Anyone-Anwendung. Es wird von einem unabhängigen Community-Mitglied entwickelt und gepflegt. Es ist kostenlos und bleibt es auch immer.",
    'about.noticeTitle': "Wichtiger Hinweis",
    'about.notice': "AnonChat verwendet bewährte kryptografische Verfahren, doch keine Software kann absolute Sicherheit garantieren, und die Kryptografie wurde nicht formell von einem unabhängigen Dritten geprüft. Du bist für deine eigene operative Sicherheit selbst verantwortlich.",
    'about.supportTitle': "Projekt unterstützen",
