    'welcome.intro1': "आप एक निजी, पीयर-टू-पीयर मैसेंजर इस्तेमाल करने जा रहे हैं। AnonChat लोगों को जोड़ने के लिए Anyone Protocol की हिडन सर्विसेज़ का उपयोग करता है।",
    'welcome.intro2': "आपके संदेश इस तरह बनाए गए हैं कि वे केवल आपके और आपके चुने हुए लोगों के बीच रहें। आपका “*.anyone” पता ऐप में आपकी पहचान है।",
    'welcome.rememberTitle': "याद रखें:",
