    'welcome.r2': "आप जो भी भेजते हैं, पाने वाला उसे कॉपी, सेव या साझा कर सकता है।",
    'welcome.r3': "कोई भी तकनीक पूरी तरह गुमनामी नहीं दे सकती।",
    'welcome.r4': "हिडन-सर्विस रूटिंग से आम तौर पर ज़्यादा निजता मिलती है, लेकिन संदेश पहुँचने और कनेक्शन में कभी-कभी देरी होना सामान्य है।",
    'welcome.poweredBy': "द्वारा संचालित",
