    'stopped.title': "AnonChat रुक गया",
    'stopped.anon': "Anyone नेटवर्क प्रोग्राम अचानक रुक गया। AnonChat दोबारा शुरू होने तक कुछ भी नहीं भेजा जाएगा।",
