    'welcome.nextTitle': "किसी से बात कैसे शुरू करें",
    'welcome.s1': "आप दोनों AnonChat खोलें और अपना-अपना .anyone पता कॉपी करें (ऊपर बाईं ओर, अवतार के नीचे)।",
    'welcome.s2': "पते किसी भरोसेमंद माध्यम से साझा करें — आमने-सामने या किसी दूसरे सुरक्षित ऐप से। किसी अजनबी के भेजे पते पर भरोसा न करें।",
    'welcome.s3': "“संपर्क जोड़ें” से एक-दूसरे को जोड़ें, फिर नमस्ते कहें। पहला संदेश एन्क्रिप्टेड सेशन शुरू करता है।",
