    'ctest.v.ok-waiting': "सब ठीक है: उनका पता मिल गया और उनके ऐप ने जवाब दिया। प्रतीक्षा में पड़े संदेश अब भेजे जा रहे हैं।",
    'ctest.v.ok-but-refused': "उनके ऐप तक पहुँचा जा सकता है, पर उसने आपके प्रतीक्षा में पड़े संदेश अस्वीकार कर दिए। उनसे AnonChat फिर से शुरू करने को कहें।",
    'ctest.v.clock': "उनके ऐप ने जवाब दिया, पर आपकी और उनकी घड़ी में कई मिनट का अंतर है। जो गलत है उसे स्वचालित समय पर कर दें। नहीं तो एक दिन से दूसरे दिन पते मिलना बंद हो सकता है।",
    'ctest.v.own-not-published': "उन तक पहुँचा जा सकता है, पर आपका अपना पता अभी प्रकाशित नहीं हुआ है, इसलिए वे आपको जवाब नहीं दे सकते। नेटवर्क स्थिति में उसके पहुँच-योग्य दिखने तक रुकें, फिर दोबारा जाँचें।",
    'ctest.v.network-down': "नेटवर्क से कनेक्शन नहीं है। अपना इंटरनेट कनेक्शन जाँचें या AnonChat फिर से शुरू करें।",
    'ctest.v.not-found': "उनका पता अभी नेटवर्क पर नहीं है। उनसे AnonChat पूरी तरह बंद करके दोबारा शुरू करने और कंप्यूटर की घड़ी स्वचालित पर रखने को कहें। आपके संदेश प्रतीक्षा में रहेंगे और पता दिखते ही चले जाएँगे।",
