    'about.title': "AnonChat के बारे में",
    'about.version': "वर्शन {v}",
    'about.intro': "AnonChat एक निजता-प्रथम, एंड-टू-एंड एन्क्रिप्टेड डेस्कटॉप मैसेंजर है जो Anyone नेटवर्क पर हिडन सर्विस के रूप में चलता है। इसमें न कोई अकाउंट है, न फ़ोन नंबर और न कोई केंद्रीय सर्वर।",
    'about.communityTitle': "स्वतंत्र सामुदायिक प्रोजेक्ट",
