export const LANGS = [
  { code: 'en', label: 'English' },
  { code: 'es', label: 'Español' },
  { code: 'fr', label: 'Français' },
  { code: 'de', label: 'Deutsch' },
  { code: 'it', label: 'Italiano' },
  { code: 'pl', label: 'Polski' },
  { code: 'pt', label: 'Português' },
  { code: 'zh', label: '简体中文' },
  { code: 'ja', label: '日本語' },
  { code: 'hi', label: 'हिन्दी' },
];

let lang = localStorage.getItem('anyonechat.lang') || pickDefault();

function pickDefault() {
  const nav = (navigator.language || 'en').slice(0, 2);
  return STRINGS[nav] ? nav : 'en';
}

const HTML_LANG = { zh: 'zh-CN' };
const htmlLang = (code) => HTML_LANG[code] || code;

export function getLang() { return lang; }

export function setLang(code) {
  if (!STRINGS[code]) return;
  lang = code;
  localStorage.setItem('anyonechat.lang', code);
  document.documentElement.lang = htmlLang(code);
}

export function t(key, vars) {
  const table = STRINGS[lang] || STRINGS.en;
  let s = table[key] ?? STRINGS.en[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, v);
  return s;
}

export function applyI18n(root = document) {
  root.querySelectorAll('[data-i18n]').forEach(el => {
    el.textContent = t(el.getAttribute('data-i18n'));
  });
  root.querySelectorAll('[data-i18n-attr]').forEach(el => {
    el.getAttribute('data-i18n-attr').split(',').forEach(pair => {
      const [attr, key] = pair.split(':').map(s => s.trim());
      if (attr && key) el.setAttribute(attr, t(key));
    });
  });
  document.documentElement.lang = htmlLang(lang);
}
